import { notFound } from 'next/navigation'
import { resourcePages } from '@/.velite'
import { EditorialPage } from '@/components/editorial-page'
import { GLOSSARY_GUIDES } from '@/lib/glossary-guides'
import { EditorialSections } from '@/components/editorial-sections'
import type { Metadata } from 'next'
import Link from 'next/link'
import { ArrowRight } from 'lucide-react'
import { GLOSSARY, getTerm, getRelatedTerms } from '@/lib/glossary'
import { Header } from '@/components/header'
import { Footer } from '@/components/footer'
import { Section } from '@/components/ui/section'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Breadcrumbs } from '@/components/ui/breadcrumbs'
import { buttonVariants } from '@/components/ui/button'
import { JsonLd } from '@/components/json-ld'
import { buildMetadata, definedTermSchema, faqSchema, webPageSchema } from '@/lib/seo'

interface PageParams {
  params: Promise<{ slug: string }>
}

export function generateStaticParams() {
  return GLOSSARY.map((term) => ({ slug: term.slug }))
}

export async function generateMetadata({ params }: PageParams): Promise<Metadata> {
  const { slug } = await params
  const editorial = resourcePages.find((page) => page.permalink === `/glossary/${slug}`)
  if (editorial) return buildMetadata({ path: editorial.permalink, title: editorial.title, absoluteTitle: editorial.seoTitle, description: editorial.metaDescription })
  const term = getTerm(slug)
  if (!term) return {}
  return buildMetadata({
    path: `/glossary/${term.slug}`,
    title: `${term.term}: Definition & Meaning`,
    description: term.metaDescription ?? term.definition.split('. ')[0],
    images: [
      {
        url: `/glossary/${term.slug}/opengraph-image`,
        width: 1200,
        height: 630,
        alt: `${term.term} definition from Aadit Technologies`,
      },
    ],
  })
}

export default async function GlossaryTermPage({ params }: PageParams) {
  const { slug } = await params
  const editorial = resourcePages.find((page) => page.permalink === `/glossary/${slug}`)
  if (editorial) return <EditorialPage page={editorial} />
  const term = getTerm(slug)
  if (!term) notFound()

  const related = getRelatedTerms(term.relatedTerms)
  const practicalQuestions =
    term.category === 'Cybersecurity'
      ? [
          'Which systems, identities, and data would be affected by this security concern?',
          'What evidence would help the team decide whether the risk is material?',
          'Who owns the next control, remediation, or monitoring decision?',
        ]
      : [
          'Which customers, data, services, or contracts make this requirement relevant?',
          'What controls and evidence would demonstrate that the requirement is operating in practice?',
          'Who is accountable for the scope, reviews, and any remediation work?',
        ]

  const path = `/glossary/${term.slug}`
  const guide = GLOSSARY_GUIDES[term.slug]
  const schemas = [
    webPageSchema({ path, name: term.term, description: term.definition }),
    definedTermSchema({
      term: term.term,
      fullForm: term.fullForm,
      definition: term.definition,
      path,
    }),
    faqSchema(term.faqs),
  ]

  return (
    <div className="flex min-h-screen w-full flex-col">
      <Header />
      <main className="flex-1">
        <JsonLd data={schemas} />

        <Section background="muted" className="border-b">
          <div className="mx-auto max-w-3xl">
            <Breadcrumbs
              items={[
                { label: 'Home', href: '/' },
                { label: 'Glossary', href: '/glossary' },
                { label: term.term, href: path },
              ]}
            />
            <div className="mt-6 flex flex-wrap items-center gap-3">
              <h1 className="text-4xl font-bold tracking-tight text-foreground md:text-5xl">
                {term.term}
              </h1>
              <Badge variant="muted">{term.category}</Badge>
            </div>
            {term.fullForm && (
              <p className="mt-3 text-lg font-medium text-muted-foreground">{term.fullForm}</p>
            )}
            {/* Definition-first: the single clear definition is the first content on the page. */}
            <p className="mt-6 text-xl leading-relaxed text-foreground md:text-2xl md:leading-relaxed">
              {term.definition}
            </p>
          </div>
        </Section>

        <Section>
          <div className="mx-auto max-w-3xl">
            <div className="space-y-5 text-lg leading-relaxed text-muted-foreground">
              {term.detail.map((para, i) => (
                <p key={i}>{para}</p>
              ))}
            </div>

            <div className="mt-10">
              <Link
                href={term.relatedService.href}
                className={buttonVariants({ variant: 'primary', size: 'lg' })}
              >
                {term.relatedService.label}
                <ArrowRight className="h-4 w-4" />
              </Link>
            </div>
          </div>
        </Section>

        <Section>
          <div className="mx-auto max-w-3xl">
            {guide && <EditorialSections sections={guide.sections} />}
            <h2 className="mt-12 text-3xl font-bold tracking-tight">{term.comparison.heading}</h2>
            <div className="mt-6 overflow-x-auto rounded-xl border">
              <table className="w-full min-w-[560px] text-left">
                <thead className="bg-muted text-sm">
                  <tr><th scope="col" className="p-4">Aspect</th><th scope="col" className="p-4">{term.comparison.heading.split(' vs. ')[0]}</th><th scope="col" className="p-4">{term.comparison.heading.split(' vs. ')[1]}</th></tr>
                </thead>
                <tbody>
                  {term.comparison.rows.map((row) => (
                    <tr key={row.aspect} className="border-t">
                      <th scope="row" className="p-4 align-top font-semibold">{row.aspect}</th>
                      <td className="p-4 align-top text-muted-foreground">{row.first}</td>
                      <td className="p-4 align-top text-muted-foreground">{row.second}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {guide && <section className="mt-12"><h2 className="text-3xl font-bold tracking-tight">Common misconceptions</h2><ul className="mt-6 list-disc space-y-4 pl-6 leading-relaxed text-muted-foreground">{guide.misconceptions.map((item) => <li key={item}>{item}</li>)}</ul></section>}
            <h2 className="mt-12 text-3xl font-bold tracking-tight">Frequently asked questions</h2>
            <div className="mt-6 space-y-6">
              {term.faqs.map(({ question, answer }) => (
                <div key={question}>
                  <h3 className="text-lg font-semibold">{question}</h3>
                  <p className="mt-2 leading-relaxed text-muted-foreground">{answer}</p>
                </div>
              ))}
            </div>
            <h2 className="mt-12 text-xl font-bold">Reference sources</h2>
            <ul className="mt-3 list-inside list-disc space-y-2">
              {term.sources.map(({ label, href }) => (
                <li key={href}>
                  <a className="text-primary underline underline-offset-4" href={href} target="_blank" rel="noopener noreferrer">{label}</a>
                </li>
              ))}
            </ul>
          </div>
        </Section>

        <Section background="muted">
          <div className="mx-auto max-w-3xl">
            <p className="text-sm font-semibold tracking-[0.18em] text-primary uppercase">
              Practical context
            </p>
            <h2 className="mt-3 text-3xl font-bold tracking-tight">
              Using {term.term} in a real decision
            </h2>
            <p className="mt-5 leading-relaxed text-muted-foreground">
              Definitions are most useful when they help a team decide what to scope, who should own
              the work, and what evidence supports the next step. Use these questions to turn the
              term into a practical conversation.
            </p>
            <ul className="mt-6 space-y-4">
              {practicalQuestions.map((question) => (
                <li key={question} className="flex gap-3 leading-relaxed text-muted-foreground">
                  <ArrowRight className="mt-1 h-4 w-4 shrink-0 text-primary" />
                  {question}
                </li>
              ))}
            </ul>
          </div>
        </Section>

        {related.length > 0 && (
          <Section background="muted">
            <div className="mx-auto max-w-3xl">
              <h2 className="mb-8 text-2xl font-bold">Related Terms</h2>
              <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
                {related.map((item) => (
                  <Link key={item.slug} href={`/glossary/${item.slug}`} className="group">
                    <Card className="flex h-full flex-col p-6 transition-colors hover:border-primary/50">
                      <h3 className="mb-2 text-lg font-bold group-hover:text-primary">
                        {item.term}
                      </h3>
                      {item.fullForm && (
                        <p className="text-xs font-medium text-muted-foreground">{item.fullForm}</p>
                      )}
                    </Card>
                  </Link>
                ))}
              </div>
            </div>
          </Section>
        )}
      </main>
      <Footer />
    </div>
  )
}
